using System;
using System.IO;
using System.Linq;
using System.Text;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace Underwater.Editor {
public static class VRSceneReview {
 const string Scene="Assets/Scenes/Underwater_Realistic.unity",Output="Renders/VRSceneReview/",Art="Assets/UnderwaterArt/VRSceneReview/";
 static Vector3[] Points(Renderer r){if(r is SkinnedMeshRenderer s)return OctopusRepairValidation.Points(s);var f=r.GetComponent<MeshFilter>();return f&&f.sharedMesh?f.sharedMesh.vertices.Select(v=>r.transform.TransformPoint(v)).ToArray():Array.Empty<Vector3>();}
 static Renderer[] Visible(Component a)=>a.GetComponentsInChildren<Renderer>().Where(r=>r.enabled&&(r is MeshRenderer||r is SkinnedMeshRenderer)).ToArray();
 static Bounds Box(Vector3[] p){var b=new Bounds(p[0],Vector3.zero);foreach(var v in p)b.Encapsulate(v);return b;}
 public static void Apply(){
  var scene=EditorSceneManager.OpenScene(Scene);Directory.CreateDirectory(Art);Directory.CreateDirectory(Output);AssetDatabase.Refresh();
  Camera.main.farClipPlane=160;Camera.main.nearClipPlane=.035f;
  // Keep tracking space at one metre per metre. Adjust only the authored start.
  var diver=UnityEngine.Object.FindFirstObjectByType<Diver>();var motor=diver.GetComponent<DiverCollisionMotor>();motor.Initialize();if(!motor.TryTeleport(new Vector3(0,-1.3f,-8.2f)))throw new Exception("Adjusted start is obstructed");
  foreach(var group in UnityEngine.Object.FindObjectsByType<LODGroup>(FindObjectsSortMode.None)){var levels=group.GetLODs();for(int i=0;i<levels.Length;i++)levels[i].screenRelativeTransitionHeight*=.65f;group.SetLODs(levels);EditorUtility.SetDirty(group);}
  foreach(var a in UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None)){
   if(a.kind=="Ray tail")continue;var points=Visible(a).SelectMany(Points).ToArray();if(points.Length==0)continue;var b=Box(points);
   var info=a.GetComponent<ReefCreatureInfo>();if(!info)info=a.gameObject.AddComponent<ReefCreatureInfo>();info.cardsEnabled=true;if(string.IsNullOrWhiteSpace(info.creatureName))info.creatureName=a.kind;if(string.IsNullOrWhiteSpace(info.fact))info.fact=Fact(a.kind);info.localFocus=a.transform.InverseTransformPoint(b.center);info.bodyRadius=Mathf.Min(1.5f,b.extents.magnitude);info.fittedFocus=true;info.observationRange=Mathf.Max(3.2f,info.observationRange);EditorUtility.SetDirty(info);
   if(a.kind=="Octopus")FitOctopus(a);
   if(a.kind=="Box jelly"||a.kind=="Comb jelly"){var driver=a.GetComponent<JellyReferenceMotion>();if(!driver)driver=a.gameObject.AddComponent<JellyReferenceMotion>();driver.comb=a.kind=="Comb jelly";driver.player=a.GetComponentInChildren<Animation>();driver.phase=Mathf.Repeat(a.transform.position.x*.173f,1);foreach(var old in a.GetComponentsInChildren<ReefImportedAnimation>())old.enabled=false;if(driver.player){driver.player.enabled=false;driver.player.playAutomatically=false;}EditorUtility.SetDirty(driver);}
   if(a.kind=="Dolphin")foreach(var r in Visible(a))foreach(var mat in r.sharedMaterials)if(mat&&mat.shader.name=="Underwater/Imported Marine Skin"){mat.SetFloat("_SmoothnessScale",.48f);mat.SetFloat("_Glossiness",.36f);mat.SetFloat("_BumpScale",.55f);EditorUtility.SetDirty(mat);}
  }
  foreach(var squid in UnityEngine.Object.FindObjectsByType<SquidSwimmer>(FindObjectsSortMode.None)){var info=squid.GetComponent<ReefCreatureInfo>();var b=Box(Visible(squid).SelectMany(Points).ToArray());info.localFocus=squid.transform.InverseTransformPoint(b.center);info.bodyRadius=12;info.fittedFocus=true;EditorUtility.SetDirty(info);}
  foreach(var r in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None))if(r.GetComponentInParent<SeaLife>()||r.GetComponentInParent<SquidSwimmer>())r.allowOcclusionWhenDynamic=false;
  foreach(var player in UnityEngine.Object.FindObjectsByType<Animation>(FindObjectsSortMode.None)){if(!player.clip)continue;var skins=player.GetComponentsInChildren<SkinnedMeshRenderer>();var bounds=new Bounds[skins.Length];for(int phase=0;phase<=40;phase++){player.clip.SampleAnimation(player.gameObject,player.clip.length*phase/40);for(int k=0;k<skins.Length;k++){var s=skins[k];var local=Points(s).Select(p=>(s.rootBone?s.rootBone:s.transform).InverseTransformPoint(p)).ToArray();if(local.Length==0)continue;var b=Box(local);if(phase==0)bounds[k]=b;else bounds[k].Encapsulate(b);}}for(int k=0;k<skins.Length;k++){var b=bounds[k];b.Expand(b.size.magnitude*.04f);skins[k].localBounds=b;EditorUtility.SetDirty(skins[k]);}player.clip.SampleAnimation(player.gameObject,0);}
  Physics.SyncTransforms();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);AssetDatabase.SaveAssets();Debug.Log("VR_SCENE_REPAIRED");Validate();
 }
 static string Fact(string kind){switch(kind){case "Octopus":return "Eight flexible arms explore the reef with sensitive suckers.";case "Box jelly":return "Its bell contracts quickly to propel it through the water. Avoid its stinging tentacles.";case "Anglerfish":return "A glowing lure helps attract prey in the dark ocean.";case "Manta":return "Broad pectoral fins propel this filter feeder through the water.";case "Reef shark":return "A powerful tail drives its steady forward swimming.";case "Lionfish":return "Venomous fin spines provide protection. Keep your hands clear.";case "Fire coral":return "This reef animal can deliver a painful sting. Avoid touching.";default:return "Watch its fins and body as it moves through its reef habitat.";}}
 static void FitOctopus(SeaLife a){
  foreach(var old in a.GetComponentsInChildren<Transform>(true).Where(t=>t.name=="Fitted octopus contact").ToArray())UnityEngine.Object.DestroyImmediate(old.gameObject);
  var surfaces=new System.Collections.Generic.List<Collider>();foreach(var skin in a.GetComponentsInChildren<SkinnedMeshRenderer>()){var points=Points(skin);var weights=skin.sharedMesh.boneWeights;for(int bone=0;bone<skin.bones.Length;bone++){int index=bone;var chosen=Enumerable.Range(0,points.Length).Where(i=>weights[i].boneIndex0==index&&weights[i].weight0>.35f).Select(i=>skin.bones[index].InverseTransformPoint(points[i])).ToArray();if(chosen.Length<8)continue;var b=Box(chosen);var go=new GameObject("Fitted octopus contact");go.layer=9;go.transform.SetParent(skin.bones[bone],false);var c=go.AddComponent<CapsuleCollider>();int axis=b.size.x>b.size.y?(b.size.x>b.size.z?0:2):(b.size.y>b.size.z?1:2);c.direction=axis;c.center=b.center;float small=axis==0?Mathf.Min(b.size.y,b.size.z):axis==1?Mathf.Min(b.size.x,b.size.z):Mathf.Min(b.size.x,b.size.y);c.radius=Mathf.Max(.001f,small*.42f);c.height=Mathf.Max(c.radius*2,b.size[axis]*.92f);surfaces.Add(c);}}
  var contact=a.GetComponent<CreatureContactSurface>();if(!contact)contact=a.gameObject.AddComponent<CreatureContactSurface>();contact.surfaces=surfaces.ToArray();EditorUtility.SetDirty(contact);
 }
 public static void Validate(){
  EditorSceneManager.OpenScene(Scene);var all=UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None);foreach(var a in all.Where(a=>a.kind!="Ray tail"))if(!a.GetComponent<ReefCreatureInfo>()||!a.GetComponent<ReefCreatureInfo>().fittedFocus)throw new Exception("Missing fitted facts: "+a.name);
  var octopus=all.First(a=>a.kind=="Octopus");var contact=octopus.GetComponent<CreatureContactSurface>();if(!contact||contact.surfaces.Length<8||contact.surfaces.Any(c=>!c||!c.enabled||c.isTrigger||c.gameObject.layer!=9))throw new Exception("Octopus contact incomplete");Physics.SyncTransforms();foreach(var c in contact.surfaces)if(contact.Distance(c.bounds.center)>.001f)throw new Exception("Octopus touch query missed collider");
  foreach(var a in all.Where(a=>a.kind=="Comb jelly"||a.kind=="Box jelly")){var motion=a.GetComponent<JellyReferenceMotion>();if(!motion||!motion.player)throw new Exception("Missing jelly animation");motion.Step(.2f);}
  ReefCollisionValidation.Run();File.WriteAllText(Output+"Validation.txt","Fitted facts: "+all.Count(a=>a.kind!="Ray tail")+"\nOctopus solid contact segments: "+contact.surfaces.Length+"\nJelly animation drivers: "+all.Count(a=>a.GetComponent<JellyReferenceMotion>())+"\nCamera far plane: "+Camera.main.farClipPlane+"\nCollision checks passed. Hardware fit/performance still require headset testing.\n");CaptureSquid();Debug.Log("VR_SCENE_VALIDATED");
 }
 public static void FinalReview(){
  AssetDatabase.Refresh();var scene=EditorSceneManager.OpenScene(Scene);RefitBounds();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);Validate();EditorSceneManager.OpenScene(Scene);var report=new StringBuilder();
  foreach(var player in UnityEngine.Object.FindObjectsByType<Animation>(FindObjectsSortMode.None)){if(!player.clip)continue;for(int phase=0;phase<=60;phase++){player.clip.SampleAnimation(player.gameObject,player.clip.length*phase/60);foreach(var s in player.GetComponentsInChildren<SkinnedMeshRenderer>()){var b=s.bounds;b.Expand(.02f);if(Points(s).Any(p=>!b.Contains(p)))throw new Exception("Animation escapes bounds: "+s.name+" phase="+phase+" bounds="+s.bounds+" actual="+Box(Points(s))+" local="+s.localBounds+" root="+s.rootBone.position+" scale="+s.rootBone.lossyScale+" renderer="+s.transform.position);}}player.clip.SampleAnimation(player.gameObject,0);}
  foreach(var driver in UnityEngine.Object.FindObjectsByType<JellyReferenceMotion>(FindObjectsSortMode.None)){var skin=driver.GetComponentInChildren<SkinnedMeshRenderer>();var before=Points(skin);driver.Step(1.3f);var after=Points(skin);float moved=before.Zip(after,(a,b)=>Vector3.Distance(a,b)).Max();if(moved<.001f)throw new Exception("Stationary jelly tissue "+driver.name);}
  var d=UnityEngine.Object.FindFirstObjectByType<Diver>();foreach(bool left in new[]{true,false}){var glove=ScubaGlove.Create(d.transform,left);if(Mathf.Abs(glove.GripAnchor.InverseTransformPoint(glove.PalmPosition).magnitude)>.001f)throw new Exception("Glove palm anchor mismatch");UnityEngine.Object.DestroyImmediate(glove.gameObject);}
  report.AppendLine("61 phases per imported animation: all vertices within render bounds.");
  foreach(var jelly in UnityEngine.Object.FindObjectsByType<DeepWaterEncounter>(FindObjectsSortMode.None).Where(a=>a.species==DeepWaterEncounter.Species.CombJelly||a.species==DeepWaterEncounter.Species.MoonJelly)){var p=jelly.transform.position;jelly.Step(0,5,p,10);if((jelly.transform.position-p).sqrMagnitude>.00001f)throw new Exception("Jelly moves on zero timestep");}
  var optimize=typeof(QuestReefBuild).GetMethod("OptimizeScene",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Static);optimize.Invoke(null,null);
  foreach(var grass in UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Where(r=>r.name=="Seagrass patch")){var lod=grass.GetComponent<LODGroup>();if(!lod||lod.GetLODs().Last().screenRelativeTransitionHeight>.0161f)throw new Exception("Grass cut off too early");}
  report.AppendLine("Quest grass cutoff <= 0.016; fish full detail >= 3.5 m; moving animals bypass baked occlusion.");
  var camera=Camera.main;camera.farClipPlane=160;camera.nearClipPlane=.035f;if(camera.TryGetComponent<ReefOptics>(out var optics))optics.enabled=false;
  var grassTarget=UnityEngine.Object.FindObjectsByType<MeshRenderer>(FindObjectsSortMode.None).Where(r=>r.name=="Seagrass patch").OrderBy(r=>(r.transform.position-d.transform.position).sqrMagnitude).First();
  foreach(float distance in new[]{3f,12f,28f}){camera.transform.position=grassTarget.bounds.center+Vector3.up*1.5f-Vector3.forward*distance;camera.transform.LookAt(grassTarget.bounds.center+Vector3.up*.4f);UnityEngine.Object.FindFirstObjectByType<ReefAtmosphere>()?.Apply(camera);ReefCorrectionAudit.Capture(camera,Output+"Grass_"+distance+"m.png");}
  File.WriteAllText(Output+"FinalReview.txt",report.ToString());EditorSceneManager.OpenScene(Scene);CaptureActors();Debug.Log("VR_FINAL_REVIEW_PASSED");
 }
 static void RefitBounds(){
  foreach(var player in UnityEngine.Object.FindObjectsByType<Animation>(FindObjectsSortMode.None)){if(!player.clip)continue;var skins=player.GetComponentsInChildren<SkinnedMeshRenderer>();var envelopes=new Bounds[skins.Length];for(int phase=0;phase<=120;phase++){player.clip.SampleAnimation(player.gameObject,player.clip.length*phase/120);for(int k=0;k<skins.Length;k++){var s=skins[k];var frame=s.rootBone?s.rootBone:s.transform;var b=Box(Points(s).Select(frame.InverseTransformPoint).ToArray());if(phase==0)envelopes[k]=b;else envelopes[k].Encapsulate(b);}}for(int k=0;k<skins.Length;k++){var s=skins[k];var b=envelopes[k];var scale=(s.rootBone?s.rootBone:s.transform).lossyScale;float minimum=Mathf.Max(.0001f,Mathf.Min(Mathf.Abs(scale.x),Mathf.Abs(scale.y),Mathf.Abs(scale.z)));b.Expand(.12f/minimum+b.size.magnitude*.04f);s.localBounds=b;EditorUtility.SetDirty(s);}player.clip.SampleAnimation(player.gameObject,0);}
 }
 public static void QuickChecks(){
  EditorSceneManager.OpenScene(Scene);Physics.SyncTransforms();var diver=UnityEngine.Object.FindFirstObjectByType<Diver>();foreach(bool left in new[]{true,false}){var glove=ScubaGlove.Create(diver.transform,left);var visual=glove.GetComponentInChildren<SkinnedMeshRenderer>().transform;if(Vector3.Distance(visual.TransformPoint(new Vector3(0,0,-.015f)),glove.Wrist.position)>.0001f)throw new Exception("Scaled hand left its grip pivot");if(Vector3.Dot((glove.FingertipPosition-glove.Wrist.position).normalized,-glove.transform.up)<.7f)throw new Exception("Hand finger direction differs from grip pose");UnityEngine.Object.DestroyImmediate(glove.gameObject);}
  foreach(var species in new[]{DeepWaterEncounter.Species.CombJelly,DeepWaterEncounter.Species.MoonJelly}){var original=UnityEngine.Object.FindObjectsByType<DeepWaterEncounter>(FindObjectsSortMode.None).First(a=>a.species==species);var clone=UnityEngine.Object.Instantiate(original.gameObject);try{var other=clone.GetComponent<DeepWaterEncounter>();var home=original.transform.position;other.transform.position=home;original.Initialize();other.Initialize();for(int frame=0;frame<180;frame++){original.Step(1f/30,5,home,10);other.Step(1f/30,5,home+Vector3.forward*20,10);if(Vector3.Distance(original.transform.position,other.transform.position)>.0001f)throw new Exception("Jelly path still depends on viewer distance");}if(Vector3.Distance(home,original.transform.position)>.6f)throw new Exception("Excess jelly drift");}finally{UnityEngine.Object.DestroyImmediate(clone);}}
  foreach(string shader in new[]{"Underwater/Reference Comb Tissue","Underwater/Translucent Jelly Tissue","Underwater/Imported Marine Skin"})if(ShaderUtil.ShaderHasError(Shader.Find(shader)))throw new Exception("Shader compilation failed: "+shader);
  foreach(bool comb in new[]{false,true}){var motion=UnityEngine.Object.FindObjectsByType<JellyReferenceMotion>(FindObjectsSortMode.None).First(m=>m.comb==comb);for(int frame=0;frame<180;frame++){motion.Step(1f/30);foreach(var skin in motion.GetComponentsInChildren<SkinnedMeshRenderer>()){var bounds=skin.bounds;bounds.Expand(.02f);if(Points(skin).Any(p=>!bounds.Contains(p)))throw new Exception("Reference jelly motion escapes bounds: "+skin.name);}}}
  File.AppendAllText(Output+"FinalReview.txt","Both hand grip pivots/directions passed. Six seconds of near/far jelly motion matched. Changed shaders compiled. Reference jelly motion stayed within bounds for six seconds.\n");EditorSceneManager.OpenScene(Scene);CaptureActors();Debug.Log("VR_QUICK_CHECKS_PASSED");
 }
 static void CaptureActors(){
  var camera=Camera.main;if(camera.TryGetComponent<ReefOptics>(out var optics))optics.enabled=false;camera.farClipPlane=160;camera.nearClipPlane=.035f;camera.fieldOfView=55;
  foreach(string kind in new[]{"Octopus","Dolphin","Comb jelly","Box jelly","Moon jelly"}){var actor=UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None).First(a=>a.kind==kind);var renderers=Visible(actor);var b=Box(renderers.SelectMany(Points).ToArray());var disabled=UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None).Where(r=>r.enabled&&!renderers.Contains(r)).ToArray();foreach(var r in disabled)r.enabled=false;RenderSettings.fog=false;RenderSettings.ambientLight=Color.gray;RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.04f,.12f,.15f);camera.transform.position=b.center+new Vector3(1,.25f,-1.5f).normalized*b.size.magnitude*1.4f;camera.transform.LookAt(b.center);
   for(int phase=0;phase<4;phase++){var motion=actor.GetComponent<JellyReferenceMotion>();if(motion)motion.Step(.55f);else foreach(var p in actor.GetComponentsInChildren<Animation>())if(p.clip)p.clip.SampleAnimation(p.gameObject,p.clip.length*phase/4);Shader.SetGlobalFloat("_ReefTime",phase*.85f);ReefCorrectionAudit.Capture(camera,Output+kind.Replace(" ","")+"_"+phase+".png");}actor.GetComponent<ReefCreatureInfo>().Preview(camera.transform);ReefCorrectionAudit.Capture(camera,Output+kind.Replace(" ","")+"_Popup.png");foreach(var r in disabled)if(r)r.enabled=true;
  }
 }
 public static void Inspect(){
  EditorSceneManager.OpenScene(Scene);Directory.CreateDirectory(Output);Physics.SyncTransforms();var sb=new StringBuilder();var diver=UnityEngine.Object.FindFirstObjectByType<Diver>();var camera=Camera.main;
  sb.AppendLine("RIG "+EditorJsonUtility.ToJson(diver.transform)+" HEAD "+EditorJsonUtility.ToJson(camera.transform));sb.AppendLine("CAMERA near="+camera.nearClipPlane+" far="+camera.farClipPlane+" fov="+camera.fieldOfView+" occlusion="+camera.useOcclusionCulling);
  foreach(var group in UnityEngine.Object.FindObjectsByType<LODGroup>(FindObjectsSortMode.None).GroupBy(g=>g.name).OrderBy(g=>g.Key))sb.AppendLine("LOD "+group.Key+" count="+group.Count()+" size="+group.First().size+" levels="+string.Join(",",group.First().GetLODs().Select(l=>l.screenRelativeTransitionHeight)));
  foreach(var group in UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None).GroupBy(a=>a.kind).OrderBy(g=>g.Key))sb.AppendLine("INFO "+group.Key+" count="+group.Count()+" missing="+group.Count(a=>!a.GetComponent<ReefCreatureInfo>())+" disabled="+group.Count(a=>a.GetComponent<ReefCreatureInfo>()&&!a.GetComponent<ReefCreatureInfo>().cardsEnabled));
  foreach(var a in UnityEngine.Object.FindObjectsByType<SeaLife>(FindObjectsSortMode.None).Where(a=>a.kind=="Dolphin"||a.kind=="Octopus"||a.kind.Contains("jelly")).GroupBy(a=>a.kind).Select(g=>g.First()))Dump(a,sb);
  var squid=UnityEngine.Object.FindFirstObjectByType<SquidSwimmer>();Dump(squid,sb);
  File.WriteAllText(Output+"Before.txt",sb.ToString());CaptureSquid();Debug.Log("VR_SCENE_INSPECTED");
 }
 static void Dump(Component a,StringBuilder sb){sb.AppendLine("ACTOR "+a.name+" pos="+a.transform.position+" scale="+a.transform.lossyScale);foreach(var c in a.GetComponents<MonoBehaviour>())sb.AppendLine(" COMP "+c.GetType().Name+" enabled="+c.enabled);foreach(var c in a.GetComponentsInChildren<Collider>(true))sb.AppendLine(" COLLIDER "+c.name+" enabled="+c.enabled+" trigger="+c.isTrigger+" size="+c.bounds.size);foreach(var r in Visible(a)){sb.AppendLine(" VISUAL "+r.name+" bounds="+r.bounds+" actual="+Box(Points(r))+" material="+string.Join(",",r.sharedMaterials.Select(m=>m?AssetDatabase.GetAssetPath(m):"null")));if(r is SkinnedMeshRenderer s)sb.AppendLine(" BONES "+string.Join(",",s.bones.Select(b=>b.name))+" mesh="+AssetDatabase.GetAssetPath(s.sharedMesh)+" root="+(s.rootBone?s.rootBone.name:"null"));}foreach(var animation in a.GetComponentsInChildren<Animation>())sb.AppendLine(" CLIP "+(animation.clip?AssetDatabase.GetAssetPath(animation.clip)+" / "+animation.clip.name+" duration="+animation.clip.length:"none"));}
 public static void CaptureSquid(){
  var squid=UnityEngine.Object.FindFirstObjectByType<SquidSwimmer>();var camera=Camera.main;var optics=camera.GetComponent<ReefOptics>();if(optics)optics.enabled=false;camera.farClipPlane=200;camera.nearClipPlane=.03f;camera.fieldOfView=55;var surfaces=Visible(squid);var b=Box(surfaces.SelectMany(Points).ToArray());var animation=squid.GetComponentInChildren<Animation>();
  foreach(var r in UnityEngine.Object.FindObjectsByType<Renderer>(FindObjectsSortMode.None))if(!surfaces.Contains(r))r.enabled=false;
  RenderSettings.fog=false;RenderSettings.ambientLight=Color.gray;RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.04f,.12f,.15f);
  foreach(float phase in new[]{0f,.25f,.5f,.75f}){if(animation&&animation.clip)animation.clip.SampleAnimation(animation.gameObject,animation.clip.length*phase);camera.transform.position=b.center+squid.transform.right*b.size.magnitude*.75f-Vector3.up*b.size.magnitude*.35f;camera.transform.LookAt(b.center);ReefCorrectionAudit.Capture(camera,Output+"SquidBottom_"+(int)(phase*100)+".png");}
 }
}
}
